//! On-disk annotation formats, ported from `moteval/formats.py`: MOTChallenge box rows
//! (`Track`, `read_mot`, `write_mot`) and MOTS mask rows (`MaskTrack`, `read_mots`,
//! `write_mots`).
//!
//! The readers accept and reject exactly the strings Python's `int()` and `float()` do
//! (`pytext`), split lines and fields as `str.splitlines`, `str.strip`, and `str.split`
//! do, and print Python's messages.

// Generated by `rust/scripts/gen_pytext_tables.py`, one entry per line.
#[rustfmt::skip]
mod pytables;
pub mod pytext;

use std::fmt;
use std::fs;
use std::path::Path;

use crate::pyfmt::repr_str;
use pytext::{PyInt, py_float, py_int, py_str};

/// One box at one frame, tagged with its track id.
///
/// For ground-truth rows `conf` is the file's 7th column (the "consider" flag); for
/// predictions it is the detection confidence. `class_id` is 1 unless the reader is asked
/// to read the class column.
#[derive(Clone, Debug, PartialEq)]
pub struct Track {
    pub frame: i64,
    pub track_id: i64,
    pub x: f64,
    pub y: f64,
    pub w: f64,
    pub h: f64,
    pub conf: f64,
    pub class_id: i64,
}

/// One RLE mask at one frame, tagged with its track id.
///
/// `rle` is the compressed counts string exactly as read from the file. Class 10 marks
/// ignore regions in MOTS GT files; the loader routes those rows, `read_mots` returns all.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MaskTrack {
    pub frame: i64,
    pub track_id: i64,
    pub class_id: i64,
    pub img_h: i64,
    pub img_w: i64,
    pub rle: String,
}

/// Which row format a row error names.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RowFormat {
    Mot,
    Mots,
}

/// Errors from reading or writing annotation files. Messages match the Python text.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum FormatError {
    /// `malformed MOT row in {path}:{lineno}: {line!r}` (or `MOTS`).
    MalformedRow {
        format: RowFormat,
        path: String,
        lineno: usize,
        line: String,
    },
    /// `MOT row without a class (column 8) in {path}:{lineno}: {line!r}`.
    RowWithoutClass {
        path: String,
        lineno: usize,
        line: String,
    },
    /// A row whose integer field Python reads but `i64` cannot hold. Python accepts the
    /// row and fails later (frame out of range, or numpy's int64 overflow); Rust stops
    /// here. The message is Rust's own.
    IntegerOutOfRange {
        path: String,
        lineno: usize,
        line: String,
    },
    /// An `OSError` (`[Errno N] text: 'path'`).
    Os(String),
    /// A `UnicodeDecodeError` from decoding the file as UTF-8.
    Decode(String),
}

impl fmt::Display for FormatError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::MalformedRow {
                format,
                path,
                lineno,
                line,
            } => {
                let name = match format {
                    RowFormat::Mot => "MOT",
                    RowFormat::Mots => "MOTS",
                };
                write!(
                    f,
                    "malformed {name} row in {path}:{lineno}: {}",
                    repr_str(line)
                )
            }
            Self::RowWithoutClass { path, lineno, line } => write!(
                f,
                "MOT row without a class (column 8) in {path}:{lineno}: {}",
                repr_str(line)
            ),
            Self::IntegerOutOfRange { path, lineno, line } => write!(
                f,
                "integer outside the 64-bit range in {path}:{lineno}: {}",
                repr_str(line)
            ),
            Self::Os(message) | Self::Decode(message) => f.write_str(message),
        }
    }
}

impl std::error::Error for FormatError {}

/// `Path.read_text()`: the file decoded as UTF-8, with Python's error text.
pub fn read_text(path: &Path) -> Result<String, FormatError> {
    let path = pytext::py_path(path);
    let bytes =
        fs::read(&path).map_err(|err| FormatError::Os(pytext::os_error_message(&err, &path)))?;
    match String::from_utf8(bytes) {
        Ok(text) => Ok(text),
        Err(err) => Err(FormatError::Decode(
            pytext::utf8_error_message(err.as_bytes()).expect("invalid UTF-8 has an error"),
        )),
    }
}

/// `Path.write_text(text)` after `path.parent.mkdir(parents=True, exist_ok=True)`.
fn write_text(path: &Path, text: &str) -> Result<(), FormatError> {
    let path = pytext::py_path(path);
    if let Some(parent) = path.parent().filter(|p| !p.as_os_str().is_empty()) {
        fs::create_dir_all(parent)
            .map_err(|err| FormatError::Os(pytext::os_error_message(&err, parent)))?;
    }
    fs::write(&path, text).map_err(|err| FormatError::Os(pytext::os_error_message(&err, &path)))
}

/// One parsed integer field: Python's `ValueError` is `None`.
fn int_field(s: &str) -> Option<PyInt> {
    py_int(s).ok()
}

/// Parse a MOTChallenge txt file into `Track` rows (`read_mot`).
///
/// Fields are comma-separated after the line is stripped. Without `class_column` the 8th
/// column is ignored and every row gets class 1; with it, a row without an 8th column is
/// malformed and a negative class is an error. A missing 7th column gives `conf` 1.0.
pub fn read_mot(path: &Path, class_column: bool) -> Result<Vec<Track>, FormatError> {
    let text = read_text(path)?;
    let path_str = py_str(path);
    let mut tracks = Vec::new();
    for (index, raw_line) in pytext::splitlines(&text).into_iter().enumerate() {
        let lineno = index + 1;
        let line = pytext::strip(raw_line);
        if line.is_empty() {
            continue;
        }
        let malformed = || FormatError::MalformedRow {
            format: RowFormat::Mot,
            path: path_str.clone(),
            lineno,
            line: line.to_owned(),
        };
        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() < if class_column { 8 } else { 6 } {
            return Err(malformed());
        }
        // Python evaluates every field inside one `try`; any ValueError is "malformed".
        let conf = if fields.len() > 6 {
            py_float(fields[6])
        } else {
            Some(1.0)
        };
        let frame = int_field(fields[0]);
        let track_id = int_field(fields[1]);
        let x = py_float(fields[2]);
        let y = py_float(fields[3]);
        let w = py_float(fields[4]);
        let h = py_float(fields[5]);
        let class_id = if class_column {
            int_field(fields[7])
        } else {
            Some(PyInt::Value(1))
        };
        let (
            Some(conf),
            Some(frame),
            Some(track_id),
            Some(x),
            Some(y),
            Some(w),
            Some(h),
            Some(class_id),
        ) = (conf, frame, track_id, x, y, w, h, class_id)
        else {
            return Err(malformed());
        };
        // `if track.class_id < 0` runs on Python's unbounded int, so a huge negative
        // class is "without a class" too.
        let class_negative = match class_id {
            PyInt::Value(v) => v < 0,
            PyInt::OutOfRange { negative } => negative,
        };
        if class_negative {
            return Err(FormatError::RowWithoutClass {
                path: path_str.clone(),
                lineno,
                line: line.to_owned(),
            });
        }
        let (PyInt::Value(frame), PyInt::Value(track_id), PyInt::Value(class_id)) =
            (frame, track_id, class_id)
        else {
            return Err(FormatError::IntegerOutOfRange {
                path: path_str.clone(),
                lineno,
                line: line.to_owned(),
            });
        };
        tracks.push(Track {
            frame,
            track_id,
            x,
            y,
            w,
            h,
            conf,
            class_id,
        });
    }
    Ok(tracks)
}

/// Python's `format(x, ".{precision}f")`: Rust's exact formatting, with Python's
/// spellings of the non-finite values.
fn format_fixed(x: f64, precision: usize) -> String {
    if x.is_nan() {
        "nan".to_owned()
    } else if x.is_infinite() {
        if x > 0.0 { "inf" } else { "-inf" }.to_owned()
    } else {
        format!("{x:.precision$}")
    }
}

/// Write `Track` rows as MOTChallenge predictions (`write_mot`).
///
/// Rows are sorted by `(frame, track_id)` (stable); column 8 holds `class_id` and the two
/// trailing fields are `-1`.
pub fn write_mot(path: &Path, tracks: &[Track]) -> Result<(), FormatError> {
    let mut rows: Vec<&Track> = tracks.iter().collect();
    rows.sort_by_key(|t| (t.frame, t.track_id));
    let lines: Vec<String> = rows
        .iter()
        .map(|t| {
            format!(
                "{},{},{},{},{},{},{},{},-1,-1",
                t.frame,
                t.track_id,
                format_fixed(t.x, 2),
                format_fixed(t.y, 2),
                format_fixed(t.w, 2),
                format_fixed(t.h, 2),
                format_fixed(t.conf, 4),
                t.class_id
            )
        })
        .collect();
    write_text(path, &join_lines(&lines))
}

/// `"\n".join(lines) + ("\n" if lines else "")`.
fn join_lines(lines: &[String]) -> String {
    let mut text = lines.join("\n");
    if !lines.is_empty() {
        text.push('\n');
    }
    text
}

/// Parse a MOTS txt file into `MaskTrack` rows (`read_mots`).
///
/// Fields are whitespace-separated; a row must have exactly six.
pub fn read_mots(path: &Path) -> Result<Vec<MaskTrack>, FormatError> {
    let text = read_text(path)?;
    let path_str = py_str(path);
    let mut tracks = Vec::new();
    for (index, raw_line) in pytext::splitlines(&text).into_iter().enumerate() {
        let lineno = index + 1;
        let line = pytext::strip(raw_line);
        if line.is_empty() {
            continue;
        }
        let row_error = |out_of_range: bool| {
            let (path, line) = (path_str.clone(), line.to_owned());
            if out_of_range {
                FormatError::IntegerOutOfRange { path, lineno, line }
            } else {
                FormatError::MalformedRow {
                    format: RowFormat::Mots,
                    path,
                    lineno,
                    line,
                }
            }
        };
        let fields = pytext::split_whitespace(line);
        if fields.len() != 6 {
            return Err(row_error(false));
        }
        let ints: Vec<Option<PyInt>> = fields[..5].iter().map(|f| int_field(f)).collect();
        if ints.iter().any(Option::is_none) {
            return Err(row_error(false));
        }
        let mut values = [0i64; 5];
        for (slot, parsed) in values.iter_mut().zip(&ints) {
            match parsed {
                Some(PyInt::Value(v)) => *slot = *v,
                _ => return Err(row_error(true)),
            }
        }
        let [frame, track_id, class_id, img_h, img_w] = values;
        tracks.push(MaskTrack {
            frame,
            track_id,
            class_id,
            img_h,
            img_w,
            rle: fields[5].to_owned(),
        });
    }
    Ok(tracks)
}

/// Write `MaskTrack` rows as a MOTS txt file (`write_mots`), sorted by `(frame,
/// track_id)` (stable).
pub fn write_mots(path: &Path, tracks: &[MaskTrack]) -> Result<(), FormatError> {
    let mut rows: Vec<&MaskTrack> = tracks.iter().collect();
    rows.sort_by_key(|t| (t.frame, t.track_id));
    let lines: Vec<String> = rows
        .iter()
        .map(|t| {
            format!(
                "{} {} {} {} {} {}",
                t.frame, t.track_id, t.class_id, t.img_h, t.img_w, t.rle
            )
        })
        .collect();
    write_text(path, &join_lines(&lines))
}

/// The sequences of `names` with no `<name>.txt` regular file in `pred_dir`, in order.
///
/// `evaluate` raises `EvalError::MissingPredictions` with these names before it scores
/// anything (Python: `not (pred_dir / f"{seq.name}.txt").is_file()`).
pub fn missing_prediction_files<'a>(
    pred_dir: &Path,
    names: impl IntoIterator<Item = &'a str>,
) -> Vec<String> {
    names
        .into_iter()
        .filter(|name| !pytext::py_join(pred_dir, format!("{name}.txt")).is_file())
        .map(str::to_owned)
        .collect()
}

/// The `rust/testdata/pytext/<topic>.json` corpus dumped by `dump_pytext.py`.
#[cfg(test)]
pub(crate) fn pytext_corpus(topic: &str) -> Vec<serde_json::Value> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../testdata/pytext")
        .join(format!("{topic}.json"));
    let text = std::fs::read_to_string(&path).expect("read the pytext corpus");
    let json: serde_json::Value = serde_json::from_str(&text).expect("parse the pytext corpus");
    json.as_array().expect("a list of cases").clone()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fixed_point_formatting_matches_python() {
        let cases = pytext_corpus("format");
        assert!(cases.len() > 3000);
        for case in &cases {
            let x = f64::from_bits(case["bits"].as_u64().expect("bits"));
            assert_eq!(format_fixed(x, 2), case["f2"], "format({x:e}, '.2f')");
            assert_eq!(format_fixed(x, 4), case["f4"], "format({x:e}, '.4f')");
        }
    }
}
